1	// Package contractsentinel report: content-addressed, persistable audit reports.
2	package contractsentinel
3	
4	import (
5		"crypto/sha256"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"os"
10		"path/filepath"
11		"sort"
12		"strings"
13	)
14	
15	// Check statuses recorded per rule in a report.
16	const (
17		StatusUnchecked   = "未检查"
18		StatusPass        = "通过"
19		StatusDefect      = "发现缺陷"
20		StatusToolMissing = "工具缺失"
21		StatusTimeout     = "超时"
22	)
23	
24	// ReportArtifact identifies the audited artifact by name and content hash.
25	type ReportArtifact struct {
26		Name string `json:"name"`
27		Hash string `json:"hash"`
28	}
29	
30	// ReportRule is one rule together with the invariant check result. The note
31	// carries the original checker description: counterexample evidence for a
32	// defect, a tool availability remark for 工具缺失, a deadline remark for 超时,
33	// or an optional remark for a passing check. It is empty for reports built
34	// only from invariant booleans.
35	type ReportRule struct {
36		ID          string `json:"id"`
37		Kind        string `json:"kind"`
38		Severity    string `json:"severity"`
39		Invariant   string `json:"invariant"`
40		RequiresABI bool   `json:"requiresABI"`
41		Version     string `json:"version"`
42		Status      string `json:"status"`
43		Note        string `json:"note,omitempty"`
44	}
45	
46	// ReportFinding binds a defect to its artifact, rule, version and evidence.
47	type ReportFinding struct {
48		ArtifactHash string `json:"artifactHash"`
49		RuleID       string `json:"ruleId"`
50		Version      string `json:"version"`
51		Severity     string `json:"severity"`
52		Invariant    string `json:"invariant"`
53		Evidence     string `json:"evidence"`
54	}
55	
56	// Report is the persisted audit result.
57	type Report struct {
58		ReportID string          `json:"reportId"`
59		Artifact ReportArtifact  `json:"artifact"`
60		Rules    []ReportRule    `json:"rules"`
61		Findings []ReportFinding `json:"findings"`
62	}
63	
64	// wireArtifact is the JSON shape of an artifact in an audit submission.
65	type wireArtifact struct {
66		Name     string `json:"name"`
67		ABI      string `json:"abi"`
68		Bytecode string `json:"bytecode"`
69		Source   string `json:"source"`
70	}
71	
72	// wireRule is the JSON shape of a rule in an audit submission.
73	type wireRule struct {
74		ID          string `json:"id"`
75		Kind        string `json:"kind"`
76		Severity    string `json:"severity"`
77		Invariant   string `json:"invariant"`
78		RequiresABI bool   `json:"requiresABI"`
79		Version     string `json:"version"`
80	}
81	
82	// CheckRecord is one imported per-rule check result: the artifact hash and
83	// rule version it was produced against, the conclusion status, and the
84	// original checker note (counterexample, tool or deadline remark).
85	type CheckRecord struct {
86		ArtifactHash string
87		RuleID       string
88		Version      string
89		Status       string
90		Note         string
91	}
92	
93	// wireCheck is the JSON shape of one entry in the checks array.
94	type wireCheck struct {
95		ArtifactHash string `json:"artifactHash"`
96		RuleID       string `json:"ruleId"`
97		Version      string `json:"version"`
98		Status       string `json:"status"`
99		Note         string `json:"note"`
100	}
101	
102	// wireInput is the JSON object accepted by the audit command.
103	type wireInput struct {
104		Artifact   wireArtifact               `json:"artifact"`
105		Rules      []wireRule                 `json:"rules"`
106		Invariants map[string]json.RawMessage `json:"invariants"`
107		Checks     []wireCheck                `json:"checks"`
108	}
109	
110	// submissionShape is the fixed-field shape of an audit submission: the agreed
111	// spellings at the top level and inside the artifact, every rule and every
112	// check record. The invariants object is a fixed top-level member but has no
113	// nested shape, so it passes through untouched: invariant names are
114	// user-defined rather than fixed fields, and "Inv" and "inv" stay two
115	// independent invariants and a padded name is not trimmed.
116	var submissionShape = fixedShape{
117		keys: []string{"artifact", "rules", "invariants", "checks"},
118		objects: map[string]fixedShape{
119			"artifact": {keys: []string{"name", "abi", "bytecode", "source"}},
120		},
121		arrays: map[string]fixedShape{
122			"rules":  {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version"}},
123			"checks": {keys: []string{"artifactHash", "ruleId", "version", "status", "note"}},
124		},
125	}
126	
127	// strictSubmissionJSON rewrites submission bytes to the fixed submission
128	// fields under their agreed spelling; see fixedShape for the recognition
129	// convention shared with the archive read side.
130	func strictSubmissionJSON(data []byte) ([]byte, error) {
131		return strictFixedJSON(data, submissionShape)
132	}
133	
134	// validateFormalCheckStatuses checks the formal "status" member of every
135	// strict check record. The strict rewrite dropped extension members, so the
136	// status seen here is the agreed-spelling one alone: a missing formal status,
137	// a non-string one, or an unsupported value rejects the whole submission
138	// even when an adjacent "StAtus" extension member carried a legal-looking
139	// value. The error names the rule the record is for so the offending entry is
140	// identifiable.
141	func validateFormalCheckStatuses(strict []byte) error {
142		var top struct {
143			Checks []map[string]json.RawMessage `json:"checks"`
144		}
145		if err := json.Unmarshal(strict, &top); err != nil {
146			return errInvalid("invalid JSON: " + err.Error())
147		}
148		for _, rec := range top.Checks {
149			where := "check record"
150			if raw, ok := rec["ruleId"]; ok {
151				var ruleID string
152				if err := json.Unmarshal(raw, &ruleID); err == nil && ruleID != "" {
153					where = "check for rule " + ruleID
154				}
155			}
156			raw, ok := rec["status"]
157			if !ok {
158				return errInvalid(where + ": status is required")
159			}
160			var status string
161			if err := json.Unmarshal(raw, &status); err != nil {
162				return errInvalid(where + ": status must be a string")
163			}
164			if !validCheckStatus(status) {
165				return errInvalid(where + ": unknown status " + status)
166			}
167		}
168		return nil
169	}
170	
171	// ParseAuditInput decodes an audit submission JSON object into domain values.
172	// Invariant values must be JSON booleans; any other type is an error. Any JSON
173	// object in the submission that repeats a member name rejects the whole
174	// submission: the decoder keeps only the last value silently, so a repeated
175	// invariant key would choose a conclusion by member order instead of giving
176	// one trustworthy result. A character the decoder would silently rewrite — an
177	// invalid UTF-8 byte, or an unpaired or wrongly ordered surrogate escape in
178	// any member name or string value, including values nested under unknown
179	// extension members — rejects the whole submission as an input error before
180	// any content is hashed, so evidence and hashes always reflect the submitted
181	// bytes rather than a U+FFFD-rewritten copy. Only the fixed fields under their
182	// agreed spelling participate: case variants and whitespace-padded names are
183	// extension data and are ignored, so they can neither override a formal value
184	// nor supply one when the formal member is missing or unsupported. Invariant
185	// names are not fixed fields — they are user-defined, compared case
186	// sensitively and never trimmed.
187	func ParseAuditInput(data []byte) (Artifact, []Rule, map[string]bool, []CheckRecord, error) {
188		if charErr := validateJSONCharacters(data); charErr != nil {
189			return Artifact{}, nil, nil, nil, errInvalid(charErr.Error())
190		}
191		if dup := findDuplicateJSONMember(data); dup != nil {
192			return Artifact{}, nil, nil, nil, errInvalid(duplicateMemberMessage(data, dup))
193		}
194		strict, err := strictSubmissionJSON(data)
195		if err != nil {
196			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
197		}
198		if err := validateFormalCheckStatuses(strict); err != nil {
199			return Artifact{}, nil, nil, nil, err
200		}
201		var in wireInput
202		if err := json.Unmarshal(strict, &in); err != nil {
203			return Artifact{}, nil, nil, nil, errInvalid("invalid JSON: " + err.Error())
204		}
205		invariants := make(map[string]bool, len(in.Invariants))
206		for key, raw := range in.Invariants {
207			// Only JSON true/false is a conclusion. Unmarshalling directly into a
208			// bool would turn null into the zero value false, which would falsely
209			// record a defect; require the token to be a boolean instead.
210			var token any
211			if err := json.Unmarshal(raw, &token); err != nil {
212				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
213			}
214			holds, ok := token.(bool)
215			if !ok {
216				return Artifact{}, nil, nil, nil, errInvalid("invariant " + key + " must be a boolean")
217			}
218			invariants[key] = holds
219		}
220		artifact := Artifact{
221			Name:     in.Artifact.Name,
222			ABI:      in.Artifact.ABI,
223			Bytecode: in.Artifact.Bytecode,
224			Source:   in.Artifact.Source,
225		}
226		rules := make([]Rule, 0, len(in.Rules))
227		for _, wr := range in.Rules {
228			rules = append(rules, Rule{
229				ID:          wr.ID,
230				Kind:        wr.Kind,
231				Severity:    wr.Severity,
232				Invariant:   wr.Invariant,
233				RequiresABI: wr.RequiresABI,
234				Version:     wr.Version,
235			})
236		}
237		checks := make([]CheckRecord, 0, len(in.Checks))
238		for _, wc := range in.Checks {
239			checks = append(checks, CheckRecord{
240				ArtifactHash: wc.ArtifactHash,
241				RuleID:       wc.RuleID,
242				Version:      wc.Version,
243				Status:       wc.Status,
244				Note:         wc.Note,
245			})
246		}
247		return artifact, rules, invariants, checks, nil
248	}
249	
250	// ArtifactHash computes the content hash of an artifact. Only the raw ABI,
251	// bytecode and source strings contribute; field boundaries are explicit
252	// (length-prefixed) so that different splits never collide. The source is
253	// hashed as a field value, never read from disk, and the name does not
254	// participate.
255	func ArtifactHash(a Artifact) string {
256		h := sha256.New()
257		h.Write([]byte("contractsentinel-artifact-v1\n"))
258		for _, field := range []string{a.ABI, a.Bytecode, a.Source} {
259			fmt.Fprintf(h, "%d\n", len(field))
260			h.Write([]byte(field))
261		}
262		sum := h.Sum(nil)
263		return hex.EncodeToString(sum)
264	}
265	
266	// validCheckStatus reports whether status is one of the four recorded check
267	// conclusions.
268	func validCheckStatus(status string) bool {
269		switch status {
270		case StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
271			return true
272		}
273		return false
274	}
275	
276	// BuildReport evaluates rules against the artifact and invariant values and
277	// imported check records and produces the report to persist. Insufficient
278	// inputs (missing ABI for a rule that requires it, missing bytecode for a
279	// symbolic rule) fail the whole submission and are never recorded as defects.
280	// Imported checks are validated as a whole: unknown rules, duplicate records,
281	// unknown statuses, missing notes, hash or version mismatches, and a rule
282	// receiving both a check record and an invariant boolean all reject the
283	// submission without producing a report.
284	func BuildReport(artifact Artifact, rules []Rule, invariants map[string]bool, checks []CheckRecord) (Report, error) {
285		if artifact.Name == "" {
286			return Report{}, errInvalid("artifact name is required")
287		}
288		hash := ArtifactHash(artifact)
289		seen := make(map[string]bool, len(rules))
290		ruleByID := make(map[string]Rule, len(rules))
291		for _, rule := range rules {
292			if rule.ID == "" {
293				return Report{}, errInvalid("rule id is required")
294			}
295			if rule.Version == "" {
296				return Report{}, errInvalid("rule " + rule.ID + " version is required")
297			}
298			if seen[rule.ID] {
299				return Report{}, errInvalid("duplicate rule id " + rule.ID)
300			}
301			seen[rule.ID] = true
302			ruleByID[rule.ID] = rule
303			if rule.RequiresABI && artifact.ABI == "" {
304				return Report{}, errInvalid("rule " + rule.ID + " requires an ABI")
305			}
306			if rule.Kind == "symbolic" && artifact.Bytecode == "" {
307				return Report{}, errInvalid("symbolic rule " + rule.ID + " requires bytecode")
308			}
309		}
310		checkByRule := make(map[string]CheckRecord, len(checks))
311		for _, check := range checks {
312			if check.RuleID == "" {
313				return Report{}, errInvalid("check rule id is required")
314			}
315			rule, ok := ruleByID[check.RuleID]
316			if !ok {
317				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown rule")
318			}
319			if _, dup := checkByRule[check.RuleID]; dup {
320				return Report{}, errInvalid("duplicate check for rule " + check.RuleID)
321			}
322			if check.ArtifactHash != hash {
323				return Report{}, errInvalid("check for rule " + check.RuleID + ": artifact hash mismatch")
324			}
325			if check.Version != rule.Version {
326				return Report{}, errInvalid("check for rule " + check.RuleID + ": version mismatch")
327			}
328			if !validCheckStatus(check.Status) {
329				return Report{}, errInvalid("check for rule " + check.RuleID + ": unknown status " + check.Status)
330			}
331			if check.Status != StatusPass && strings.TrimSpace(check.Note) == "" {
332				return Report{}, errInvalid("check for rule " + check.RuleID + ": note is required for status " + check.Status)
333			}
334			if _, hasInvariant := invariants[rule.Invariant]; hasInvariant {
335				return Report{}, errInvalid("rule " + check.RuleID + ": both a check record and an invariant value are provided")
336			}
337			checkByRule[check.RuleID] = check
338		}
339		report := Report{
340			Artifact: ReportArtifact{Name: artifact.Name, Hash: hash},
341			Rules:    []ReportRule{},
342			Findings: []ReportFinding{},
343		}
344		for _, rule := range rules {
345			status := StatusUnchecked
346			note := ""
347			if check, ok := checkByRule[rule.ID]; ok {
348				status = check.Status
349				note = check.Note
350			} else if holds, checked := invariants[rule.Invariant]; checked {
351				if holds {
352					status = StatusPass
353				} else {
354					status = StatusDefect
355				}
356			}
357			report.Rules = append(report.Rules, ReportRule{
358				ID:          rule.ID,
359				Kind:        rule.Kind,
360				Severity:    rule.Severity,
361				Invariant:   rule.Invariant,
362				RequiresABI: rule.RequiresABI,
363				Version:     rule.Version,
364				Status:      status,
365				Note:        note,
366			})
367			if status == StatusDefect {
368				evidence := note
369				if evidence == "" {
370					evidence = "invariant " + rule.Invariant + " does not hold"
371				}
372				report.Findings = append(report.Findings, ReportFinding{
373					ArtifactHash: hash,
374					RuleID:       rule.ID,
375					Version:      rule.Version,
376					Severity:     rule.Severity,
377					Invariant:    rule.Invariant,
378					Evidence:     evidence,
379				})
380			}
381		}
382		report.ReportID = ReportID(report)
383		return report, nil
384	}
385	
386	// canonicalRule is the order-independent view of a rule used for the id. The
387	// note is omitted when empty so reports built only from invariant booleans
388	// keep their original ids.
389	type canonicalRule struct {
390		ID          string `json:"id"`
391		Kind        string `json:"kind"`
392		Severity    string `json:"severity"`
393		Invariant   string `json:"invariant"`
394		RequiresABI bool   `json:"requiresABI"`
395		Version     string `json:"version"`
396		Status      string `json:"status"`
397		Note        string `json:"note,omitempty"`
398	}
399	
400	// canonicalFinding is the order-independent view of a finding used for the id.
401	type canonicalFinding struct {
402		ArtifactHash string `json:"artifactHash"`
403		RuleID       string `json:"ruleId"`
404		Version      string `json:"version"`
405		Severity     string `json:"severity"`
406		Invariant    string `json:"invariant"`
407		Evidence     string `json:"evidence"`
408	}
409	
410	// canonicalReport is the deterministic content a report id is computed from.
411	type canonicalReport struct {
412		ArtifactHash string             `json:"artifactHash"`
413		Name         string             `json:"name"`
414		Rules        []canonicalRule    `json:"rules"`
415		Findings     []canonicalFinding `json:"findings"`
416	}
417	
418	// canonicalize renders a report into its order-independent form.
419	func canonicalize(report Report) canonicalReport {
420		cr := canonicalReport{
421			ArtifactHash: report.Artifact.Hash,
422			Name:         report.Artifact.Name,
423		}
424		for _, rule := range report.Rules {
425			cr.Rules = append(cr.Rules, canonicalRule{
426				ID: rule.ID, Kind: rule.Kind, Severity: rule.Severity,
427				Invariant: rule.Invariant, RequiresABI: rule.RequiresABI,
428				Version: rule.Version, Status: rule.Status, Note: rule.Note,
429			})
430		}
431		sort.Slice(cr.Rules, func(i, j int) bool { return cr.Rules[i].ID < cr.Rules[j].ID })
432		for _, finding := range report.Findings {
433			cr.Findings = append(cr.Findings, canonicalFinding{
434				ArtifactHash: finding.ArtifactHash, RuleID: finding.RuleID,
435				Version: finding.Version, Severity: finding.Severity,
436				Invariant: finding.Invariant, Evidence: finding.Evidence,
437			})
438		}
439		sort.Slice(cr.Findings, func(i, j int) bool { return cr.Findings[i].RuleID < cr.Findings[j].RuleID })
440		return cr
441	}
442	
443	// ReportID returns the content-addressed identifier of a report. The id binds
444	// the artifact hash, name, complete rule definitions, the invariant value
445	// used by each rule (unchecked and explicit pass are distinct), and the
446	// findings. Rule order, invariant key order and unrelated invariant keys do
447	// not influence it.
448	func ReportID(r Report) string {
449		data, err := json.Marshal(canonicalize(r))
450		if err != nil {
451			panic(err) // canonical values are all strings and bools
452		}
453		sum := sha256.Sum256(data)
454		return hex.EncodeToString(sum[:])
455	}
456	
457	// validateReport checks every archive legality condition against r. It is the
458	// single definition of a legal report: the id and artifact hash are 64
459	// lowercase hex characters, the id matches the content, the artifact name is
460	// present, rule ids are present and unique with non-empty versions, statuses
461	// use the five recorded values, tool-missing and timeout notes are
462	// non-blank, and 发现缺陷 rules correspond one-to-one with findings whose
463	// artifact hash, version, severity, invariant and evidence match the rule.
464	// The same conditions apply to submissions and to stored archives: a
465	// recomputed id never makes an invalid report legal. fail is errInvalid for
466	// submissions and errCorrupt for stored archives.
467	func validateReport(r Report, fail func(string) error) error {
468		if !validReportID(r.ReportID) {
469			return fail("report id " + r.ReportID + " is not a 64-character lowercase hex string")
470		}
471		if r.Artifact.Name == "" {
472			return fail("report " + r.ReportID + " artifact name is required")
473		}
474		if !validReportID(r.Artifact.Hash) {
475			return fail("report " + r.ReportID + " artifact hash is not a 64-character lowercase hex string")
476		}
477		if ReportID(r) != r.ReportID {
478			return fail("report content does not match id " + r.ReportID)
479		}
480		seenRule := make(map[string]bool, len(r.Rules))
481		defectByID := make(map[string]ReportRule)
482		for _, rule := range r.Rules {
483			if rule.ID == "" {
484				return fail("report " + r.ReportID + " has a rule with an empty id")
485			}
486			if seenRule[rule.ID] {
487				return fail("report " + r.ReportID + " has duplicate rule id " + rule.ID)
488			}
489			seenRule[rule.ID] = true
490			if rule.Version == "" {
491				return fail("report " + r.ReportID + " rule " + rule.ID + " has an empty version")
492			}
493			switch rule.Status {
494			case StatusUnchecked, StatusPass, StatusDefect, StatusToolMissing, StatusTimeout:
495			default:
496				return fail("report " + r.ReportID + " rule " + rule.ID + " has unknown status " + rule.Status)
497			}
498			if (rule.Status == StatusToolMissing || rule.Status == StatusTimeout) && strings.TrimSpace(rule.Note) == "" {
499				return fail("report " + r.ReportID + " rule " + rule.ID + " status " + rule.Status + " has no note")
500			}
501			if rule.Status == StatusDefect {
502				defectByID[rule.ID] = rule
503			}
504		}
505		seenFinding := make(map[string]bool, len(r.Findings))
506		for _, f := range r.Findings {
507			if f.RuleID == "" {
508				return fail("report " + r.ReportID + " has a finding with an empty rule id")
509			}
510			rule, ok := defectByID[f.RuleID]
511			if !ok {
512				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " does not match a 发现缺陷 rule")
513			}
514			if seenFinding[f.RuleID] {
515				return fail("report " + r.ReportID + " has a duplicate finding for rule " + f.RuleID)
516			}
517			seenFinding[f.RuleID] = true
518			if f.ArtifactHash != r.Artifact.Hash {
519				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has artifact hash " + f.ArtifactHash + ", want " + r.Artifact.Hash)
520			}
521			if f.Version != rule.Version {
522				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has version " + f.Version + ", want " + rule.Version)
523			}
524			if f.Severity != rule.Severity {
525				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has severity " + f.Severity + ", want " + rule.Severity)
526			}
527			if f.Invariant != rule.Invariant {
528				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has invariant " + f.Invariant + ", want " + rule.Invariant)
529			}
530			wantEvidence := rule.Note
531			if wantEvidence == "" {
532				wantEvidence = "invariant " + rule.Invariant + " does not hold"
533			}
534			if f.Evidence != wantEvidence {
535				return fail("report " + r.ReportID + " finding for rule " + f.RuleID + " has evidence " + f.Evidence + ", want " + wantEvidence)
536			}
537		}
538		for id := range defectByID {
539			if !seenFinding[id] {
540				return fail("report " + r.ReportID + " defect rule " + id + " has no finding")
541			}
542		}
543		return nil
544	}
545	
546	// validStoredReport validates archive contents.
547	func validStoredReport(r Report) error {
548		return validateReport(r, func(msg string) error { return errCorrupt(msg) })
549	}
550	
551	// validSubmittedReport validates a submission before any store operation.
552	func validSubmittedReport(r Report) error {
553		return validateReport(r, func(msg string) error { return errInvalid(msg) })
554	}
555	
556	// duplicateArchiveError classifies an archive that repeats a JSON member as
557	// corrupt and names the requested report id, the decoded member name and the
558	// object carrying it (with array position and rule id when applicable).
559	func duplicateArchiveError(id string, data []byte, dup *duplicateMemberError) error {
560		return errCorrupt("report " + id + " archive is corrupt: " + duplicateMemberMessage(data, dup))
561	}
562	
563	// reportShape is the fixed-field shape of a stored report archive: the agreed
564	// spellings at the top level and inside the artifact, every rule and every
565	// finding. The trusted content of a report is carried by these fixed fields
566	// alone; case variants, whitespace-padded names and unknown members are
567	// extension data and never reach the decoder.
568	var reportShape = fixedShape{
569		keys: []string{"reportId", "artifact", "rules", "findings"},
570		objects: map[string]fixedShape{
571			"artifact": {keys: []string{"name", "hash"}},
572		},
573		arrays: map[string]fixedShape{
574			"rules":    {keys: []string{"id", "kind", "severity", "invariant", "requiresABI", "version", "status", "note"}},
575			"findings": {keys: []string{"artifactHash", "ruleId", "version", "severity", "invariant", "evidence"}},
576		},
577	}
578	
579	// strictReportJSON rewrites archive bytes to the fixed report fields under
580	// their original spelling; see fixedShape for the recognition convention
581	// shared with the submission side.
582	func strictReportJSON(data []byte) ([]byte, error) {
583		return strictFixedJSON(data, reportShape)
584	}
585	
586	// loadStoredReport parses archive bytes for id and fully validates them.
587	func loadStoredReport(data []byte, id string) (Report, error) {
588		// Read-side counterpart of the submission check: json.Unmarshal silently
589		// keeps the last value for a repeated member, so an archive that writes a
590		// rule status as 发现缺陷 and then 通过 would decode to whichever came
591		// last. The recomputed id and the rule/finding correspondence all operate
592		// on that last-wins value and could therefore pass, accepting an archive
593		// with two conflicting conclusions. Any repeated member in any object
594		// makes the archive corrupt, regardless of the last value.
595		if dup := findDuplicateJSONMember(data); dup != nil {
596			return Report{}, duplicateArchiveError(id, data, dup)
597		}
598		strict, err := strictReportJSON(data)
599		if err != nil {
600			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
601		}
602		var r Report
603		if err := json.Unmarshal(strict, &r); err != nil {
604			return Report{}, errCorrupt("invalid JSON in report " + id + ": " + err.Error())
605		}
606		if r.ReportID != id {
607			return Report{}, errCorrupt("report id " + r.ReportID + " does not match requested id " + id)
608		}
609		if err := validStoredReport(r); err != nil {
610			return Report{}, err
611		}
612		return r, nil
613	}
614	
615	// saveReportHook, when set, is invoked after the archive existence check and
616	// before the atomic publish. It lets tests simulate another process racing to
617	// claim the same report id.
618	var saveReportHook func(finalPath string)
619	
620	// SaveReport persists a report under the store directory. The store is safe
621	// for concurrent writers: identical reports share one file and all
622	// submissions succeed, different reports never overwrite each other, and
623	// readers only ever observe complete files. A submission is fully validated
624	// before any store operation, so an invalid report creates no store and no
625	// files. A pre-existing file with the same id must be a valid archive of the
626	// same report; a corrupted archive makes the submission fail while keeping the
627	// original file, even when the corruption appears only during the save. The
628	// first successfully archived bytes are never replaced by later submissions.
629	func SaveReport(dir string, r Report) error {
630		if err := validSubmittedReport(r); err != nil {
631			return err
632		}
633		if err := os.MkdirAll(dir, 0o755); err != nil {
634			return err
635		}
636		finalPath := filepath.Join(dir, r.ReportID+".json")
637		if existing, err := os.ReadFile(finalPath); err == nil {
638			if _, err := loadStoredReport(existing, r.ReportID); err != nil {
639				return err
640			}
641			return nil
642		} else if !os.IsNotExist(err) {
643			return err
644		}
645		data, err := json.Marshal(r)
646		if err != nil {
647			return err
648		}
649		tmp, err := os.CreateTemp(dir, ".report-*.tmp")
650		if err != nil {
651			return err
652		}
653		tmpPath := tmp.Name()
654		cleanup := func() { os.Remove(tmpPath) }
655		if _, err := tmp.Write(data); err != nil {
656			tmp.Close()
657			cleanup()
658			return err
659		}
660		if err := tmp.Sync(); err != nil {
661			tmp.Close()
662			cleanup()
663			return err
664		}
665		if err := tmp.Close(); err != nil {
666			cleanup()
667			return err
668		}
669		if saveReportHook != nil {
670			saveReportHook(finalPath)
671		}
672		if err := os.Link(tmpPath, finalPath); err != nil {
673			cleanup()
674			if os.IsExist(err) {
675				existing, readErr := os.ReadFile(finalPath)
676				if readErr != nil {
677					return readErr
678				}
679				if _, err := loadStoredReport(existing, r.ReportID); err != nil {
680					return err
681				}
682				return nil
683			}
684			return err
685		}
686		cleanup()
687		return nil
688	}
689	
690	// LoadReport reads and verifies a report by id. The id must be 64 lowercase
691	// hex characters; missing, corrupted or tampered archives produce a clear
692	// error. The store is only read, never created or modified.
693	func LoadReport(dir, id string) (Report, error) {
694		if !validReportID(id) {
695			return Report{}, errInvalid("invalid report id " + id + ": want 64 lowercase hex characters")
696		}
697		data, err := os.ReadFile(filepath.Join(dir, id+".json"))
698		if err != nil {
699			if os.IsNotExist(err) {
700				return Report{}, errNotFound("report " + id + " not found")
701			}
702			return Report{}, err
703		}
704		return loadStoredReport(data, id)
705	}
706	
707	type errNotFound string
708	
709	func (e errNotFound) Error() string { return string(e) }
710	
711	type errCorrupt string
712	
713	func (e errCorrupt) Error() string { return string(e) }
714

