300							where, path, abs, data)
301					}
302					i += 12
303				case isLowSurrogate(r):
304					// A low surrogate with no preceding high surrogate: this
305					// includes a low-before-high ordering, whose first escape is
306					// the unpaired low one.
307					return charError(charKindEscape,
308						fmt.Sprintf("unpaired low surrogate escape \\u%04X", r),
309						where, path, abs, data)
310				default:
311					i += 6
312				}
313			default:
314				return nil // malformed JSON: defer
