1	package main
2	
3	import (
4		"bytes"
5		"os"
6		"path/filepath"
7		"strings"
8		"testing"
9	
10		"github.com/gzhysuiioo/contractsentinel-audit/contractsentinel"
11	)
12	
13	// 本文件在真实命令行进程边界上回归 audit 提交的字符合法性拒绝：
14	// JSON 字符串里的非法 UTF-8 字节、未配对或错序的 Unicode 代理转义必须让
15	// audit 以非零状态退出、stderr 说明字符编码/Unicode 转义问题并指出位置、
16	// stdout 为空；尚不存在的报告目录不创建，已有报告原样保留。合法字符
17	// （含正确成对的代理转义与直接书写的同一字符）继续成功，且两种写法的
18	// 产物哈希与报告标识一致。
19	
20	// charsetArtifactJSON / charsetRulesJSON 是结构合法的提交片段。
21	const charsetArtifactJSON = `{"name":"Vault","abi":"abi","bytecode":"0x1","source":"Vault.sol"}`
22	const charsetRulesJSON = `[{"id":"r1","kind":"static","severity":"high","invariant":"inv","requiresABI":false,"version":"1.0.0"}]`
23	
24	// charsetDefectDoc 用给定的原始 note JSON 片段拼出一份“发现缺陷”提交，
25	// 其检查记录绑定正确的产物哈希与规则版本。
26	func charsetDefectDoc(hash, noteJSON string) string {
27		check := `{"artifactHash":"` + hash + `","ruleId":"r1","version":"1.0.0","status":"发现缺陷","note":` + noteJSON + `}`
28		return `{"artifact":` + charsetArtifactJSON + `,"rules":` + charsetRulesJSON + `,"checks":[` + check + `]}`
29	}
30	
31	// --- note 含孤立高代理项转义：整份拒绝，输出干净、无存储副作用 ---
32	
33	func TestCLIAuditLoneSurrogateNoteRejectedCleanly(t *testing.T) {
34		bin := auditBinary(t)
35		work := t.TempDir()
36		hash := contractsentinelArtifactHashForCharset()
37		input := writeInput(t, work, "bad.json",
38			charsetDefectDoc(hash, `"反例：\uD800重入路径"`))
39		store := filepath.Join(work, "nested", "missing-store")
40	
41		stdout, stderr, code := runCLIAudit(t, bin, input, store)
42		if code == 0 {
43			t.Fatal("a lone surrogate escape in the note must exit non-zero")
44		}
45		if !strings.Contains(stderr, "Unicode escape") {
46			t.Fatalf("stderr must classify the problem as a Unicode escape issue:\n%s", stderr)
47		}
48		if !strings.Contains(stderr, "surrogate") {
49			t.Fatalf("stderr must name the unpaired surrogate:\n%s", stderr)
50		}
51		if !strings.Contains(stderr, "note") {
52			t.Fatalf("stderr must locate the offending note field:\n%s", stderr)
53		}
54		for _, marker := range []string{"byte offset", "line ", "column"} {
55			if !strings.Contains(stderr, marker) {
56				t.Fatalf("stderr must point at the position (%q):\n%s", marker, stderr)
57			}
58		}
59		assertNoPartialReport(t, stdout)
60		if _, err := os.Stat(store); !os.IsNotExist(err) {
61			t.Fatalf("rejected submission must not create the store directory: %v", err)
62		}
63	}
64	
65	// --- 孤立代理项出现在未知扩展成员的嵌套内容里：同样整份拒绝 ---
66	
67	func TestCLIAuditLoneSurrogateInExtensionRejected(t *testing.T) {
68		bin := auditBinary(t)
69		work := t.TempDir()
70		doc := `{"artifact":` + charsetArtifactJSON + `,"rules":` + charsetRulesJSON +
71			`,"mystery":{"nested":[{"deep":"x\uDC00y"}]}}`
72		input := writeInput(t, work, "bad.json", doc)
73		store := filepath.Join(work, "reports")
74	
75		stdout, stderr, code := runCLIAudit(t, bin, input, store)
76		if code == 0 {
77			t.Fatal("a lone surrogate inside an unknown extension must exit non-zero")
78		}
79		if !strings.Contains(stderr, "Unicode escape") || !strings.Contains(stderr, "surrogate") {
80			t.Fatalf("stderr must classify and name the surrogate problem:\n%s", stderr)
81		}
82		assertNoPartialReport(t, stdout)
83		if _, err := os.Stat(store); !os.IsNotExist(err) {
84			t.Fatalf("rejected submission must not create the store directory: %v", err)
85		}
86	}
87	
88	// --- 源码字符串含非法 UTF-8 字节：在哈希计算前拒绝 ---
89	
90	func TestCLIAuditInvalidUTF8SourceRejectedCleanly(t *testing.T) {
91		bin := auditBinary(t)
92		work := t.TempDir()
93		// 真正拼入一个 0xFF 字节，而不是字面的反斜杠文本。
94		doc := `{"artifact":{"name":"Vault","abi":"abi","bytecode":"0x1","source":"x` + "\xFF" + `y"},"rules":[]}`
95		input := writeInput(t, work, "bad.json", doc)
96		store := filepath.Join(work, "nested", "missing-store")
97	
98		stdout, stderr, code := runCLIAudit(t, bin, input, store)
99		if code == 0 {
100			t.Fatal("an invalid UTF-8 byte in the source must exit non-zero")
101		}
102		if !strings.Contains(stderr, "character encoding") || !strings.Contains(stderr, "UTF-8") {
103			t.Fatalf("stderr must classify the problem as a character encoding issue:\n%s", stderr)
104		}
105		if !strings.Contains(stderr, "source") {
106			t.Fatalf("stderr must locate the offending source field:\n%s", stderr)
107		}
108		if !strings.Contains(stderr, "byte offset") {
109			t.Fatalf("stderr must point at the byte offset:\n%s", stderr)
110		}
111		assertNoPartialReport(t, stdout)
112		if _, err := os.Stat(store); !os.IsNotExist(err) {
113			t.Fatalf("rejected submission must not create the store directory: %v", err)
114		}
115	}
116	
117	// --- 失败提交不得登记成合约缺陷/工具缺失/超时，也不得留下临时文件 ---
118	
119	func TestCLIAuditBadCharsNoStatusFragmentsOrTempFiles(t *testing.T) {
120		bin := auditBinary(t)
121		work := t.TempDir()
122		hash := contractsentinelArtifactHashForCharset()
123		input := writeInput(t, work, "bad.json",
124			charsetDefectDoc(hash, `"ce\uD800"`))
125		store := filepath.Join(work, "reports")
126	
127		stdout, _, code := runCLIAudit(t, bin, input, store)
128		if code == 0 {
129			t.Fatal("bad characters must fail the submission")
130		}
131		for _, marker := range []string{"reportId", "findings", "发现缺陷", "工具缺失", "超时", "未检查", "通过"} {
132			if strings.Contains(stdout, marker) {
133				t.Fatalf("stdout must not leak a partial report fragment %q:\n%s", marker, stdout)
134			}
135		}
136		// 存储目录即便被创建（本例未创建），也不得残留临时文件。
137		if entries, err := os.ReadDir(work); err == nil {
138			for _, e := range entries {
139				if strings.HasPrefix(e.Name(), ".report-") && strings.HasSuffix(e.Name(), ".tmp") {
140					t.Fatalf("rejected submission left a temporary file: %s", e.Name())
141				}
142			}
143		}
144	}
145	
146	// --- 已有报告时字符问题失败：原有报告保持原样，不新增文件 ---
147	
148	func TestCLIAuditBadCharsKeepsExistingReports(t *testing.T) {
149		bin := auditBinary(t)
150		work := t.TempDir()
151		store := filepath.Join(work, "reports")
152	
153		// 先落一份完全合法的报告（不变式 false 产生缺陷）。
154		good := writeInput(t, work, "good.json", `{
155			"artifact": `+charsetArtifactJSON+`,
156			"rules": `+charsetRulesJSON+`,
157			"invariants": {"inv": false}
158		}`)
159		if _, stderr, code := runCLIAudit(t, bin, good, store); code != 0 {
160			t.Fatalf("valid setup audit must succeed: %s", stderr)
161		}
162		before, err := listFiles(store)
163		if err != nil {
164			t.Fatal(err)
165		}
166		if len(before) != 1 {
167			t.Fatalf("setup expected 1 report, got %v", before)
168		}
169		existingPath := filepath.Join(store, before[0])
170		existingBytes, err := os.ReadFile(existingPath)
171		if err != nil {
172			t.Fatal(err)
173		}
174	
175		// 再提交一份 note 含孤立代理项的提交（哈希与版本均正确，仅字符非法）。
176		hash := contractsentinelArtifactHashForCharset()
177		bad := writeInput(t, work, "bad.json", charsetDefectDoc(hash, `"ce\uD800"`))
178		if _, _, code := runCLIAudit(t, bin, bad, store); code == 0 {
179			t.Fatal("invalid submission must exit non-zero")
180		}
181	
182		after, err := listFiles(store)
183		if err != nil {
184			t.Fatal(err)
185		}
186		if len(after) != len(before) || after[0] != before[0] {
187			t.Fatalf("rejected submission changed the store contents:\nbefore=%v\nafter=%v", before, after)
188		}
189		kept, err := os.ReadFile(existingPath)
190		if err != nil {
191			t.Fatal(err)
192		}
193		if !bytes.Equal(kept, existingBytes) {
194			t.Fatal("rejected submission modified the existing report bytes")
195		}
196	}
197	
198	// --- 合法成对代理转义与直接书写的同一字符：哈希、报告标识、证据一致 ---
199	
