321	// 原文中合法的 U+FFFD 与“转义反斜线 + uD800 文本”都不得被误判。
322	func TestParseAuditLiteralReplacementAndEscapedBackslashAccepted(t *testing.T) {
323		for _, noteJSON := range []string{
324			`"原有替换字符 � 保留"`,        // 直接书写的 U+FFFD
325			`"路径 C:\\uD800\\note"`, // JSON 体为 \\uD800，即反斜线加普通文本
326		} {
327			in := charSubmission(noteJSON)
328			if _, _, _, _, err := ParseAuditInput(in); err != nil {
329				t.Errorf("ordinary-U+FFFD/escaped-backslash input must stay legal: %v\ninput=%s", err, in)
330			}
331		}
332	}
