201	// --- diff：任一侧归档含重复成员，整体失败且不输出局部差异 ---
202	
203	func TestCLIDiffDuplicateMemberEitherSideFailsCleanly(t *testing.T) {
204		bin := auditBinary(t)
205		work := t.TempDir()
206		store := filepath.Join(work, "reports")
207		hash := mixedArtifactHash(t)
208		artifact := mixedCheckArtifact()
209		beforeReport := auditDiffReport(t, bin, work, store, "before.json", artifact, diffRules(), diffBeforeChecks(hash))
210		afterReport := auditDiffReport(t, bin, work, store, "after.json", artifact, diffRules(), diffAfterChecks(hash))
211		beforeID := beforeReport.ReportID
212		afterID := afterReport.ReportID
213	
214		// Keep clean bytes of both sides in separate setup stores, so one side can
215		// be restored while the other is corrupted (re-auditing into the same store
216		// would itself fail against the corrupt existing archive).
217		cleanBefore := mustMarshalStoreReport(t, bin, filepath.Join(work, "clean-b"), "before.json", artifact, hash, "before")
218		cleanAfter := mustMarshalStoreReport(t, bin, filepath.Join(work, "clean-a"), "after.json", artifact, hash, "after")
219	
220		dupStatus := func(data []byte) []byte {
221			old := `"status":"` + contractsentinel.StatusPass + `"`
222			new := `"status":"` + contractsentinel.StatusDefect + `","status":"` + contractsentinel.StatusPass + `"`
223			out := bytes.Replace(data, []byte(old), []byte(new), 1)
224			if bytes.Equal(out, data) {
225				t.Fatal("test setup: replacement did not change the archive")
226			}
227			return out
228		}
229		writeArchive := func(id string, data []byte) {
230			if err := os.WriteFile(filepath.Join(store, id+".json"), data, 0o644); err != nil {
231				t.Fatal(err)
232			}
233		}
234	
235		// 第二份损坏。
236		writeArchive(afterID, dupStatus(cleanAfter))
237		stdout, stderr, code := runCLIDiff(t, bin, store, beforeID, afterID)
238		assertDupFailure(t, stdout, stderr, code, afterID, `"status"`, "rules[")
239		for _, marker := range []string{`"results"`, `"summary"`, contractsentinel.ChangeNewDefect, contractsentinel.StatusUnchecked} {
240			if strings.Contains(stdout, marker) {
241				t.Fatalf("stdout must not leak a partial diff %q:\n%s", marker, stdout)
242			}
243		}
244	
245		// 第一份损坏、第二份恢复。
246		writeArchive(afterID, cleanAfter)
247		writeArchive(beforeID, dupStatus(cleanBefore))
248		stdout, stderr, code = runCLIDiff(t, bin, store, beforeID, afterID)
249		assertDupFailure(t, stdout, stderr, code, beforeID, `"status"`)
250		if stdout != "" {
251			t.Fatalf("stdout must stay empty on failure:\n%s", stdout)
252		}
253	
254		// 失败的比较不修复、不覆盖任何一侧归档。
255		if kept, err := os.ReadFile(filepath.Join(store, beforeID+".json")); err != nil || !bytes.Equal(kept, dupStatus(cleanBefore)) {
256			t.Fatalf("failed diff must leave the corrupt first archive untouched: %v", err)
257		}
258		if kept, err := os.ReadFile(filepath.Join(store, afterID+".json")); err != nil || !bytes.Equal(kept, cleanAfter) {
259			t.Fatalf("failed diff must leave the restored second archive untouched: %v", err)
260		}
261	}
262	
263	// mustMarshalStoreReport audits one side into a dedicated fresh store and
264	// returns the archived bytes, so tests can restore main-store archives.
265	func mustMarshalStoreReport(t *testing.T, bin, store, name string, artifact cliWireArtifact, hash, side string) []byte {
266		t.Helper()
267		checks := diffAfterChecks(hash)
268		if side == "before" {
269			checks = diffBeforeChecks(hash)
270		}
271		r := auditDiffReport(t, bin, t.TempDir(), store, name, artifact, diffRules(), checks)
272		data, err := os.ReadFile(filepath.Join(store, r.ReportID+".json"))
273		if err != nil {
274			t.Fatal(err)
275		}
276		return data
277	}
278	
279	// --- audit 保存遇到同标识已有归档含重复成员：不能当成保存成功，原文件保留 ---
280	
281	func TestCLIAuditDuplicateExistingArchiveFailsAndKeepsFile(t *testing.T) {
282		bin := auditBinary(t)
283		work := t.TempDir()
284		store := filepath.Join(work, "reports")
285		id := auditOneReport(t, bin, work, store)
286		path := filepath.Join(store, id+".json")
287		injectArchiveDuplicate(t, store, id,
288			`"status":"`+contractsentinel.StatusPass+`"`,
289			`"status":"`+contractsentinel.StatusDefect+`","status":"`+contractsentinel.StatusPass+`"`)
290		before, err := os.ReadFile(path)
291		if err != nil {
292			t.Fatal(err)
293		}
294	
295		// 用完全相同的合法提交再审计一次：同标识归档已损坏，必须失败。
296		input := writeStructInput(t, work, "again.json", mixedCheckInput(mixedArtifactHash(t)))
297		stdout, stderr, code := runCLIAudit(t, bin, input, store)
298		if code == 0 {
299			t.Fatal("audit against a duplicate-member existing archive must exit non-zero")
300		}
301		if !strings.Contains(strings.ToLower(stderr), "duplicate") || !strings.Contains(stderr, "corrupt") {
302			t.Fatalf("stderr must report duplicate-member corruption:\n%s", stderr)
303		}
304		if stdout != "" {
305			t.Fatalf("failed audit must print nothing to stdout:\n%s", stdout)
306		}
307		after, err := os.ReadFile(path)
308		if err != nil {
309			t.Fatalf("corrupt archive must be kept: %v", err)
310		}
311		if !bytes.Equal(after, before) {
312			t.Fatal("failed audit must leave the corrupt archive untouched")
313		}
314	}
315

